// Runs the Valheim generator, built to WebAssembly, off the page's thread.
// map.js and map_bg.wasm beside this file are generated by the Valheim
// generator's build; this file is written by hand.
import init, * as generator from "./map.js";

const ready = init();
const CALLS = new Set(["tile", "overlay", "legend", "places", "point", "measure"]);

self.onmessage = async (event) => {
  await ready;
  const { id, call, args } = event.data;
  if (!CALLS.has(call)) {
    self.postMessage({ id, error: `unknown call ${call}` });
    return;
  }
  const result = generator[call](...args);
  // Pixels go back without copying; text as it is.
  self.postMessage(
    { id, result },
    result instanceof Uint8Array ? [result.buffer] : [],
  );
};
